// STEP 1 — Inspect attachments + stop self-triggering loops.
// n8n Code nodes DROP binary by default.
// We return { json, binary } to carry the CSV file forward.

const item = $input.item;
let triggerData = {};
try { triggerData = $('Gmail Trigger').first() || {}; } catch(e) {}
const jsonData = triggerData.json || item.json || {};
const binaryData = triggerData.binary || item.binary || {};

const subject = (jsonData.subject || '').toLowerCase();
const from    = jsonData.from?.value?.[0]?.address || '';
const toAddr  = (jsonData.to  || [])[0]?.address   || '';

// Loop guard — stop bot reply emails re-triggering the workflow
const isBotReply = (
  subject.includes('no csv attached') ||
  subject.includes('forecast ready')  ||
  subject.includes('forecast failed') ||
  (subject.startsWith('re:') && subject.includes('forecast'))
);

if (isBotReply) {
  return {
    json: {
      hasCsv: false,
      isLoop: true,
      csvBinaryKey: null,
      csvFileName: null,
      allBinaryKeys: [],
      fromEmail: from,
      toEmail: toAddr,
      subject: jsonData.subject || ''
    },
    binary: {}
  };
}

// Detect CSV in binary data (any key, by fileName or mimeType)
const csvBinaryKey = Object.keys(binaryData).find(k => {
  const b = binaryData[k];
  const name = (b.fileName || b.name || '').toLowerCase();
  const mime = (b.mimeType || '').toLowerCase();
  return name.endsWith('.csv') || mime === 'text/csv' || mime === 'application/csv';
});

// Fallback: check $json.attachments[] array (older n8n versions)
let csvJsonMeta = null;
const jsonAttachments = jsonData.attachments || [];
if (!csvBinaryKey && Array.isArray(jsonAttachments)) {
  csvJsonMeta = jsonAttachments.find(a => {
    const name = (a.name || a.filename || '').toLowerCase();
    const mime = (a.mimeType || '').toLowerCase();
    return name.endsWith('.csv') || mime === 'text/csv' || mime === 'application/csv';
  });
}

const hasCsv = !!(csvBinaryKey || csvJsonMeta);

let csvFileName = null;
if (csvBinaryKey) {
  csvFileName = binaryData[csvBinaryKey].fileName ||
                binaryData[csvBinaryKey].name     ||
                (csvBinaryKey + '.csv');
} else if (csvJsonMeta) {
  csvFileName = csvJsonMeta.name || csvJsonMeta.filename || 'attachment.csv';
}

const allBinaryKeys = Object.keys(binaryData);

// Return { json, binary } — binary MUST be returned or downstream nodes lose the file
return {
  json: {
    hasCsv,
    isLoop: false,
    csvBinaryKey: csvBinaryKey || null,
    csvFileName,
    allBinaryKeys,
    subject: jsonData.subject || '',
    fromEmail: from,
    toEmail: toAddr
  },
  binary: binaryData
};

// STEP 2 — Parse subject params + forward binary to HTTP Request.

const item = $input.item;
const j    = item.json;
const subject = j.subject || '';

let mode    = 'quick';
let periods = 30;

const paramMatch = subject.match(/\[?FORECAST:?([a-zA-Z]+)?:?(\d+)?\]?/i);
if (paramMatch) {
  if (paramMatch[1] && ['quick','full'].includes(paramMatch[1].toLowerCase())) {
    mode = paramMatch[1].toLowerCase();
  }
  if (paramMatch[2]) {
    const p = parseInt(paramMatch[2]);
    if (!isNaN(p) && p >= 1 && p <= 365) periods = p;
  }
}

const csvFileName  = j.csvFileName  || 'attachment.csv';
const csvBinaryKey = j.csvBinaryKey || 'attachment_0';
const datasetName  = csvFileName.replace(/\.csv$/i, '').replace(/[^a-zA-Z0-9_-]/g, '_');

// MUST return binary so HTTP Request node can send the CSV file
return {
  json: {
    mode,
    periods,
    datasetName,
    csvAttachmentName: csvFileName,
    csvBinaryKey,
    fromEmail: j.fromEmail || '',
    toEmail:   j.toEmail   || '',
    originalSubject: subject,
    emailDate: new Date().toISOString()
  },
  binary: item.binary
};

// STEP 3 — Parse API response safely
let apiResponseRaw = $input.item.json.data || $input.item.json.response || $input.item.json;
let apiResponse;

try {
  apiResponse = (typeof apiResponseRaw === 'string') ? JSON.parse(apiResponseRaw) : apiResponseRaw;
} catch (e) {
  apiResponse = { success: false, error: "Failed to parse API response: " + String(apiResponseRaw).substring(0, 500) };
}

return { 
  json: apiResponse 
};

// STEP 4 — Prepare details for email.
const apiResponse = $input.item.json;
const charts = apiResponse.charts || [];
const priorityOrder = ['forecast', 'comparison', 'error_dist', 'period_revenue', 'time_series', 'acf_pacf'];

// Sort charts
const sortedCharts = [...charts].sort((a, b) => {
  const idxA = priorityOrder.findIndex(k => (a.filename || '').toLowerCase().includes(k));
  const idxB = priorityOrder.findIndex(k => (b.filename || '').toLowerCase().includes(k));
  return (idxA === -1 ? 999 : idxA) - (idxB === -1 ? 999 : idxB);
});

const chartUrls = sortedCharts.slice(0, 5).map(c => ({
  url:      `http://forecast_api:8000/outputs/${c.run_id}/${c.filename}`,
  filename: c.filename,
  run_id:   c.run_id
}));

const leaderboard = apiResponse.leaderboard || [];
const medals = ['🥇','🥈','🥉','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];
let leaderboardHtml = '';
if (leaderboard.length > 0) {
  leaderboardHtml = `<table style="width:100%;border-collapse:collapse;font-size:13px;"><thead><tr style="background:#2d3748;color:white;"><th style="padding:8px;text-align:left;">#</th><th style="padding:8px;text-align:left;">Model</th><th style="padding:8px;text-align:right;">RMSE</th><th style="padding:8px;text-align:right;">R²</th></tr></thead><tbody>${leaderboard.slice(0,10).map((m, i) => `<tr style="background:${i%2===0?'#f7fafc':'white'};"><td style="padding:8px;">${medals[i]||i+1}</td><td style="padding:8px;font-weight:${i===0?'bold':'normal'}">${m.model}</td><td style="padding:8px;text-align:right;font-family:monospace;">${Number(m.rmse).toLocaleString('en-IN',{maximumFractionDigits:2})}</td><td style="padding:8px;text-align:right;font-family:monospace;">${Number(m.r2).toFixed(4)}</td></tr>`).join('')}</tbody></table>`;
}

// Generate Recommendations HTML
const recs = apiResponse.recommendations || [];
let recommendationsHtml = '';
if (recs.length > 0) {
  recommendationsHtml = `<div style="display:grid;grid-template-columns:1fr;gap:12px;margin:16px 0;">` + 
    recs.map(r => `
    <div style="background:#f8fafc;border-left:4px solid ${r.color || '#4299e1'};padding:12px;border-radius:6px;">
      <div style="display:flex;align-items:center;margin-bottom:4px;">
        <span style="font-size:18px;margin-right:8px;">${r.icon || '🚀'}</span>
        <strong style="color:#2d3748;font-size:14px;">${r.title}</strong>
      </div>
      <p style="margin:0;color:#4a5568;font-size:12px;line-height:1.4;">${r.description}</p>
      ${r.tooltip ? `<div style="margin-top:6px;font-size:11px;color:${r.color || '#4299e1'};font-weight:600;">→ ${r.tooltip}</div>` : ''}
    </div>`).join('') + 
    `</div>`;
}

function fmt(v) {
  if (!v) return '—';
  if (v >= 1e7) return '₹' + (v/1e7).toFixed(2) + ' Cr';
  if (v >= 1e5) return '₹' + (v/1e5).toFixed(2) + ' L';
  return '₹' + Number(v).toLocaleString('en-IN',{maximumFractionDigits:2});
}

// Get data from Parse node
const parseNode = $('Parse Email & Params').item.json;

return {
  json: {
    ...apiResponse,
    chartUrls,
    chartCount: chartUrls.length,
    leaderboardHtml,
    recommendationsHtml,
    totalForecast: fmt(apiResponse.total_forecast),
    avgForecast:   fmt(apiResponse.avg_forecast),
    fromEmail:     parseNode.fromEmail,
    toEmail:       parseNode.toEmail,
    originalSubject: parseNode.originalSubject
  }
};

const apiData = $('Prepare Chart List').item.json;
const binaryData = $input.item.binary || {};

// Generate Market Trend HTML
const trendPct = apiData.market_trend_pct || 0;
const trendDir = apiData.market_trend_direction || 'higher';
const trendColor = trendDir === 'higher' ? '#48bb78' : '#e53e3e';
const trendIcon  = trendDir === 'higher' ? '📈' : '📉';

const marketTrendHtml = `
<div style="background:#ffffff;border-radius:10px;padding:20px;text-align:center;border:1px solid #e2e8f0;margin-bottom:20px;box-shadow:0 4px 6px -1px rgba(0,0,0,0.1);border-top: 4px solid ${trendColor};">
  <div style="font-size:14px;color:#718096;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">Market Trend Analysis</div>
  <div style="font-size:32px;font-weight:800;color:${trendColor};">
    ${trendIcon} ${trendPct}% ${trendDir.toUpperCase()}
  </div>
  <div style="font-size:13px;color:#a0aec0;margin-top:6px;">Comparing Predicted Average vs. Historical Average</div>
</div>
`;

// Collect all valid binary property names for attachment
const attachmentKeys = Object.keys(binaryData).filter(key => 
  key.startsWith('chart_') && binaryData[key].data
).join(',');

return {
  json: {
    toEmail:        apiData.fromEmail,
    subject:        `✅Foresee Ready: ${apiData.dataset} | Best: ${apiData.best_model} | RMSE: ${Number(apiData.rmse).toLocaleString('en-IN')}`,
    leaderboardHtml: apiData.leaderboardHtml,
    recommendationsHtml: apiData.recommendationsHtml,
    marketTrendHtml,
    dataset:        apiData.dataset,
    bestModel:      apiData.best_model,
    rmse:           apiData.rmse,
    r2:             apiData.r2,
    totalForecast:  apiData.totalForecast,
    avgForecast:    apiData.avgForecast,
    forecastPeriods: apiData.forecast_periods,
    dateFrom:       apiData.date_from,
    dateTo:         apiData.date_to,
    mode:           apiData.mode,
    runId:          apiData.run_id,
    elapsedS:       apiData.elapsed_s,
    chartCount:     apiData.chartCount,
    plainText:      apiData.summary_text,
    attachments:    attachmentKeys
  },
  binary: binaryData  // MUST forward binary so email node gets the charts
};

