=<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; margin: 0; padding: 20px; background: #f0f4f8; }
    .container { max-width: 680px; margin: auto; background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.1); }
    .header { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); color: white; padding: 32px 28px; }
    .body { padding: 28px; }
    .metric-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; margin: 20px 0; }
    .metric-card { background: #f7fafc; border-radius: 8px; padding: 16px; text-align: center; border-top: 3px solid #4299e1; }
    .metric-card .value { font-size: 22px; font-weight: bold; color: #2d3748; }
    .metric-card .label { font-size: 12px; color: #718096; margin-top: 4px; }
    .section-title { font-size: 16px; font-weight: bold; color: #2d3748; margin: 24px 0 12px 0; border-bottom: 2px solid #e2e8f0; padding-bottom: 8px; }
    .footer { background: #2d3748; color: #a0aec0; padding: 16px 28px; font-size: 12px; text-align: center; }
    .best-model-badge { background: #48bb78; color: white; border-radius: 6px; padding: 6px 14px; font-weight: bold; display: inline-block; }
    .run-info { background: #ebf8ff; border: 1px solid #bee3f8; border-radius: 6px; padding: 12px 16px; font-size: 13px; color: #2c5282; margin: 16px 0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1 style="margin:0 0 6px 0;font-size:22px;">🛒 Retail Sales Forecast Ready</h1>
      <p style="margin:0;opacity:0.8;font-size:14px;">Your dataset has been processed by the ML pipeline + sanT</p>
    </div>
    <div class="body">
      <p style="margin:0 0 8px 0;color:#718096;font-size:13px;">🏆 BEST AUTO-SELECTED MODEL</p>
      <span class="best-model-badge">{{ $json.bestModel }}</span>
      <div class="run-info" style="margin-top:16px;">
        📊 Run ID: <strong>{{ $json.runId }}</strong> &nbsp;|&nbsp;
        ⏱️ Completed in <strong>{{ $json.elapsedS }}s</strong> &nbsp;|&nbsp;
        🖼️ <strong>{{ $json.chartCount }}</strong> chart(s) attached
      </div>
      <div class="metric-grid">
        <div class="metric-card" style="border-top-color:#48bb78;"><div class="value">{{ $json.totalForecast }}</div><div class="label">Total Forecast</div></div>
        <div class="metric-card" style="border-top-color:#4299e1;"><div class="value">{{ $json.avgForecast }}</div><div class="label">Avg / Period</div></div>
        <div class="metric-card" style="border-top-color:#ed8936;"><div class="value">{{ $json.forecastPeriods }}</div><div class="label">Periods Ahead</div></div>
      </div>
      <div class="run-info">🗓️ Forecast Range: <strong>{{ $json.dateFrom }}</strong> → <strong>{{ $json.dateTo }}</strong></div>

      {{ $json.marketTrendHtml }}

      {{ $json.recommendationsHtml ? `<div class="section-title">🚀 Strategic Growth Recommendations</div>${$json.recommendationsHtml}` : '' }}

      <div class="section-title">📋 Model Leaderboard</div>
      {{ $json.leaderboardHtml }}

      <div class="section-title">📝 Full Summary</div>
      <pre style="background:#f7fafc;padding:16px;border-radius:8px;font-size:12px;overflow:auto;white-space:pre-wrap;">{{ $json.plainText }}</pre>
      <p style="color:#718096;font-size:13px;margin-top:20px;">📎Forecast chart images are attached to this email.</p>
    </div>
    <div class="footer">
      🤖 Retail Sales Forecasting Bot &nbsp;|&nbsp; Powered by n8n + ML Pipeline v2.0 + sanT<br>
      Send a CSV with subject <code>forecast:quick:30</code> for a new forecast
    </div>
  </div>
</body>
</html>
